#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""答案缓存的键 —— **纯逻辑,零 IO,不碰库不调模型**。

缓存规格 §10.1 + 附录 A-2。方法是规格钉死的,这里不重新选型:
**对规范化结构做带密钥的 HMAC-SHA256**。
附录 A-2 写了为什么选它、比过什么(裸哈希):
> 「优于只哈希问题文字;相较裸哈希不便直接枚举短问题,增加服务端密钥维护。」

## 这个文件要防的那一件事

> **一个答案什么时候还适用,取决于「谁在问、看得见什么资料、哪一版配置」——
> 而这些东西全都不在问题文字里。**

规格 §B-3 记的就是这个:只按问题文本复用可以把命中率做得很高,
**却会错用资料版本或别人身份的答案**。

所以这里的工作不是「算个哈希」,是**把「还适用吗」这件事拆成一串必须相同的字段**。
键只是那串字段的指纹 —— 字段漏登的话,哈希帮不上任何忙:

> **A-2 的局限栏自己写着:「字段漏登无法由哈希弥补;
> 哈希不是权限检查,也不保证内容正确。」**

## 四条硬规矩(每条都对应一种会错用答案的方式)

### ① 缺一个必填字段 → **抛**,不拿空串顶

这是最要紧的一条。拿空串顶的后果:

    项目甲、没拿到 release_manifest_id  → 键里那一位是 ""
    项目甲、另一次也没拿到              → 键里那一位也是 ""
    两次算出**同一个键** → 第二次复用了第一次的答案

而那两次可能跑在**不同的发布版本**上。
> **一个把「我不知道」填成空串的键,和一个真的两边一致的键,
> 在那串哈希上长得一模一样。**

规格 §17.1 第 3 步说的也是这个:「无法确定则**绕过**」——
绕过是产品行为,而这一层只负责**说不出来就抛**,由调用方决定绕过还是拒绝。

### ② `None` / `""` / `0` / `false` 必须算出**不同**的键

「这个任务没有会话」(`None`)和「会话是空的」(`""`)是两件事;
「没有记忆版本」和「记忆版本是 0」也是。
规范化时**带上类型标记**,不把它们折成同一个字符串。

### ③ 规范化**只排对象的键**,不动数组顺序、不动文本一个字

规格 §10.1:「对象键顺序规范化,**数组顺序和文本内容保持**;
**不自动删除否定词、空白语义、数字或时间单位**」。

为什么:
· 排序数组会让 `["A","B"]` 和 `["B","A"]` 撞 —— 而它们可能是
  **两种不同顺序的检索结果**,喂给模型会得到不同答案
· 「删掉空白」会让「不含」和「不 含」撞;
  「归一化数字」会让「3 天」和「3.0 天」撞 —— 而工期差一天是业务差别

### ④ 密钥**不进返回值、不进异常、不进任何日志**

它是服务端密钥(规格:「密钥通过现有密钥服务引用,**不进入页面或 Trace**」)。
这个文件只接受**已经解析好的密钥字节**,自己不读环境变量、不碰 keychain ——
谁解析谁负责不泄露。异常文字里只说「缺哪个字段」,绝不回显任何值。

## 它不做什么

- **不做权限检查。** 键里带 `principal_or_verified_scope` 只是让
  不同身份算出不同的键;**交付前仍然要重新鉴权**(规格 §13.2 的线性化点)。
- **不判答案对不对。**
- **不决定绕过。** 它只会「算得出」或「抛」,绕过是上层策略。
- **不生成 Redis key。** 规格:「条目 ID 是服务端标识,
  **不把用户输入拼进 Redis key**」—— 那一层在 `cache/store`。
"""
import hashlib
import hmac
import json

# 键的结构版本。**改了字段表就要改它** —— 否则新旧两套字段算出的键
# 会落在同一个命名空间里,而「版本不同」这件事在哈希上看不出来。
键结构版本 = "ak1"

# ── 必填字段 ────────────────────────────────────────────────────────────
#
# 规格 §10.1 给了字段契约。这里按「少了它答案就可能不再适用」分成两组:
#
# ⚠️ **必填的意思是「说不出来就抛」,不是「填个默认值」。** 见文件头第 ① 条。
必填 = (
    "key_schema_version",            # 这套字段表的版本
    "project_id", "environment",     # 跨项目、跨环境**绝不复用**
    "application_id",
    "release_manifest_id",           # 哪一版发布包
    "cache_policy_version",          # 哪一版缓存策略
    "namespace_generation",          # 失效代次(清空范围时 +1)
    "principal_or_verified_scope",   # 谁在问(或经核验的共享范围)
    "authorization_epoch",           # 授权代次(撤权后 +1)
    "input_payload_hash",            # 这次的输入
    "knowledge_manifest_revision",   # 看得见哪一版资料
    "retrieval_pipeline_revision",   # 怎么检索的
    "model_connection_revision",     # 哪个连接
    "model_resolved_revision",       # **端点实际返回的型号**,不是我们请求的那个
    "generation_parameters",         # 温度之类 —— 改了答案就会变
    "output_schema_revision",        # 要什么形状的输出
    "locale",                        # 语言
)

# 可以不给,但**必须显式写出来「为什么这个任务不需要它」**。
#
# ⚠️ 规格 §10.1:「**不含会影响任务的字段必须说明理由**」。
# 所以这里不是「可选」,是「**要么给值,要么给理由**」——
# 一个静默缺席的字段,和一个想清楚了不需要的字段,在键上长得一样。
要么给值要么给理由 = (
    "relevant_conversation_hash",    # 多轮任务才有
    "memory_revision",               # 用记忆的任务才有
)


class 算不出键(Exception):
    """说不出这个键 —— **绝不返回一个「差不多」的键**。

    ⚠️ 异常文字里只出现**字段名**,不出现任何字段值,也绝不出现密钥。
    """


def _规范(值):
    """把一个值折成**带类型标记**的规范形式。

    ⚠️ 带类型标记是有意的(文件头第 ② 条):
    `None` / `""` / `0` / `False` 折出来必须不一样 ——
    「没有会话」和「会话是空串」是两件事。

    ⚠️ **只排对象的键,不动数组顺序,不动字符串一个字**(第 ③ 条)。
    """
    if 值 is None:
        return ["null"]
    if isinstance(值, bool):          # ⚠️ bool 要在 int 之前判:它是 int 的子类
        return ["bool", 值]
    if isinstance(值, int):
        return ["int", str(值)]        # 用字符串避免 1 和 1.0 折在一起
    if isinstance(值, float):
        return ["float", repr(值)]
    if isinstance(值, str):
        return ["str", 值]             # **原样**:不 strip、不改大小写、不归一化数字
    if isinstance(值, (list, tuple)):
        # **保序** —— 检索结果的顺序会改变答案
        return ["list"] + [_规范(x) for x in 值]
    if isinstance(值, dict):
        # **只在这里排序**:对象的键没有语义顺序
        return ["dict"] + [[k, _规范(值[k])] for k in sorted(值, key=str)]
    raise 算不出键(f"键里出现了认不出的类型:{type(值).__name__} —— "
                 f"**不猜怎么序列化它**。先决定它该怎么规范化,再加进键")


def 规范化(字段):
    """字段 dict → 规范 JSON 字符串(确定性的)。

    `sort_keys` 不够用:它只排最外层,而嵌套的 dict 也要排;
    而且它会把 `None` 写成 `null`、把 `0` 和 `0.0` 写成不同字面量
    但把 `0` 和 `False` 写成 `0` / `false`(这个还好),
    **而 `""` 和 `None` 在某些写法里会被下游当成同一回事**。
    所以先过一遍 `_规范` 打上类型标记。
    """
    return json.dumps(_规范(字段), ensure_ascii=False, separators=(",", ":"))


def 查字段(字段, *, 不需要的理由=None):
    """只检查字段齐不齐,**不算键**。给策略编辑页的「技术详情」用。

    返回问题清单(空 = 齐了)。分开成一个函数是为了让页面能
    **在算键之前**就把缺什么告诉人 —— 而不是等到运行时抛。
    """
    理由 = dict(不需要的理由 or {})
    问 = []
    缺 = [k for k in 必填 if k not in 字段]
    if 缺:
        问.append(f"**缺这些必填字段**:{缺} —— "
                  f"规格 §10.1 要求它们不可随意删除。"
                  f"**不许用空串顶**:两次都缺同一个字段时,"
                  f"它们会算出同一个键,于是跨版本/跨身份复用了答案")
    空值 = [k for k in 必填 if k in 字段 and 字段[k] is None]
    if 空值:
        问.append(f"这些必填字段给的是 `None`:{空值} —— "
                  f"「拿不到」要**抛**,由上层决定绕过还是拒绝"
                  f"(规格 §17.1 第 3 步:无法确定则绕过),"
                  f"而不是把 `None` 当成一个合法的键值")
    for k in 要么给值要么给理由:
        if k not in 字段 and not (理由.get(k) or "").strip():
            问.append(f"`{k}` 没给值,也没写「为什么这个任务不需要它」—— "
                      f"规格 §10.1:**不含会影响任务的字段必须说明理由**。"
                      f"一个静默缺席的字段,和一个想清楚了不需要的字段,"
                      f"在键上长得一样")
    野 = sorted(set(理由) - set(要么给值要么给理由))
    if 野:
        问.append(f"给了这些字段的「不需要理由」,而它们是**必填**的:{野} —— "
                  f"必填字段不许用理由豁免掉")
    return 问


def 算键(字段, *, 密钥, 不需要的理由=None):
    """算这次请求的缓存键。返回 `(十六进制指纹, 规范化后的字符串)`。

    `密钥` 是**已经解析好的** bytes(服务端密钥)。这个文件自己不去读它 ——
    谁解析谁负责不泄露(规格:密钥不进入页面或 Trace)。

    ⚠️ 第二个返回值是**规范化后的结构**,给「技术详情」里做脱敏差异对比用。
    **它不含密钥**,但含字段值 —— 调用方要按字段权限决定给谁看。
    """
    if not isinstance(密钥, (bytes, bytearray)) or len(密钥) < 16:
        # ⚠️ 只说长度不够,**不回显密钥本身**(连前几位都不给)
        raise 算不出键("密钥不合格(要 bytes,且至少 16 字节)—— "
                     "**不拿一个弱密钥算键**:键的作用之一是"
                     "让人不能靠枚举短问题去猜别人的缓存内容")
    问 = 查字段(字段, 不需要的理由=不需要的理由)
    if 问:
        raise 算不出键("；".join(问))
    if 字段.get("key_schema_version") != 键结构版本:
        raise 算不出键(
            f"`key_schema_version` 是 {字段.get('key_schema_version')!r},"
            f"而这份实现是 {键结构版本!r} —— **不混算**:"
            f"两套字段表算出的键落在同一个命名空间里,"
            f"而「版本不同」这件事在哈希上看不出来")
    料 = 规范化(字段)
    指纹 = hmac.new(bytes(密钥), 料.encode("utf-8"), hashlib.sha256).hexdigest()
    return 指纹, 料
